// Supabase Database Webhook signature verification (HMAC-SHA256).
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SHARED_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SHARED_SECRET not configured'); }
const sig = $input.first().headers['x-webhook-signature'] || '';
const raw = $input.first().binary?.data?.data
  ? Buffer.from($input.first().binary.data.data, 'base64').toString('utf8')
  : JSON.stringify($input.first().json);
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
  throw new Error('Invalid webhook signature');
}
return [{ json: $input.first().json }];

// Diff old vs new onboarding_status, build the payload for the portal.
// KAIA-762: We now emit supabaseClientId (the Supabase UUID) and let
// sc-lookup resolve it to the portal cuid before the write node runs.
// The sc-lookup node is the single place that knows about the ID scheme
// translation; this node is purely about business-logic classification.
const payload = $input.first().json;
const rec = payload.record || payload.body?.record || {};
const old = payload.old_record || payload.body?.old_record || {};

if (!rec.id) { throw new Error('Webhook payload missing record.id'); }
if (rec.onboarding_status === old.onboarding_status) {
  return [];
}

const newStatus = rec.onboarding_status;
if (newStatus !== 'live' && newStatus !== 'paused' && newStatus !== 'cancelled') {
  return [];
}

const previousStatus = old.onboarding_status || null;
const actor = $env.KAIROPERATOR_ACTOR || 'system';
const reason = $env.KAIROPERATOR_REASON || null;

const notes = JSON.stringify({
  previous_status: previousStatus,
  new_status: newStatus,
  actor,
  reason,
});

// supabaseClientId is the Supabase UUID from chatbot_clients.id.
// sc-lookup will translate this to the portal cuid via
// POST /api/internal/lookup-client-id-from-supabase.
return [{
  json: {
    supabaseClientId: rec.id,
    milestone: 'status_change',
    completedAt: new Date().toISOString(),
    notes,
    previous_status: previousStatus,
    new_status: newStatus,
  }
}];

// KAIA-762: resolve Supabase UUID (supabaseClientId) to portal cuid (clientId)
// by calling the internal lookup route. Throws (triggers error branch → Slack)
// when the UUID is not found in the portal — the watcher cannot write a
// ChatbotActivity row without a resolved clientId.
const supabaseClientId = $input.first().json.supabaseClientId;
if (!supabaseClientId) { throw new Error("Webhook payload missing supabaseClientId"); }

const portalUrl = $env.PORTAL_API_URL;
const portalKey = $env.PORTAL_API_KEY;
if (!portalUrl || !portalKey) { throw new Error("PORTAL_API_URL or PORTAL_API_KEY not configured"); }

const response = await fetch(portalUrl + "/api/internal/lookup-client-id-from-supabase", {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    "X-Kairikos-Internal-Key": portalKey,
  },
  body: JSON.stringify({ supabaseClientId }),
});

if (response.status === 404) {
  // Unknown Supabase UUID — alert via Slack and do not write.
  // Throwing here routes to the error branch (sc-slack-err).
  const detail = await response.text();
  throw new Error("Lookup returned 404 for supabaseClientId=" + supabaseClientId + ": " + detail);
}

if (!response.ok) {
  throw new Error("Lookup failed (" + response.status + "): " + await response.text());
}

const { clientId } = await response.json();

// Pass through all original fields from classify node + resolved clientId
return [{ json: { ...$input.first().json, clientId } }];
